await tools.write({ file_path: "D:\\lean\\tmp\\sheaf\\xif\\paper\\_S1953Extra.lean", content: `import tmp.sheaf.xif.paper.S1953CoherentGaloisActual

noncomputable section
set_option linter.checkUnivs false
set_option maxHeartbeats 2000000

namespace LeanFormal.IUT.XiFPaper.S1953Extra

open CategoryTheory
open LeanFormal.IUT.XiFPaper.S1854CoherentCategoryActual
open LeanFormal.IUT.XiFPaper.S1953CoherentGaloisActual

attribute [local instance] S1854CoherentCategory01

theorem test_toPreGalois :
    S1953GaloisCategory.toPreGaloisCategory = S1953PreGaloisCategory :=
  Subsingleton.elim _ _

end LeanFormal.IUT.XiFPaper.S1953Extra
`});
const p = await tools.pwsh({ description: "Probe Galois-to-PreGalois coherence", command: "lake env lean tmp/sheaf/xif/paper/_S1953Extra.lean", workdir: "D:\\lean", timeoutMs: 900000 });
console.log("exit:", p.exitCode);
console.log(p.stdout.text.slice(0, 4000));
console.log("STDERR:", p.stderr.text.slice(0, 2000));
", "description": "Probe coherence lemma"}

